import base64
import pathlib
import subprocess
import sys
import tempfile

subprocess.run(
    [sys.executable, "-m", "pip", "install", "-q", "qiskit", "numpy", "scipy", "matplotlib"],
    check=True,
)

SOURCES_B64 = {'Day37/3-1.py': '', 'Day37/3-2.py': '', 'Day37/3-3.py': '', 'Day37/3-4.py': '', 'Day37/3-5.py': '', 'Day37/3-6.py': '', 'Day37/3-7.py': '', 'Day37/3-8.py': ''}

EXECUTION_ORDER = ['Day37/3-1.py', 'Day37/3-2.py', 'Day37/3-3.py', 'Day37/3-4.py', 'Day37/3-5.py', 'Day37/3-6.py', 'Day37/3-7.py', 'Day37/3-8.py']

with tempfile.TemporaryDirectory(prefix="quantum-ml-day37-") as tmp:
    root = pathlib.Path(tmp)
    for relative_path, payload in SOURCES_B64.items():
        destination = root / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(base64.b64decode(payload))
    for relative_path in EXECUTION_ORDER:
        day, name = relative_path.split("/", 1)
        label = f"{day}/{name}"
        print(f"COLAB_SOURCE_START {label}", flush=True)
        subprocess.run([sys.executable, name], cwd=root / day, check=True)
        print(f"COLAB_SOURCE_OK {label}", flush=True)
print("COLAB_DAY37_SOURCE_EXECUTION_OK", flush=True)
